def longestPalindrome(s):
    res_l = res_r = 0
    def expand(l, r):
        nonlocal res_l, res_r
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if r - l > res_r - res_l:
                res_l, res_r = l, r
            l -= 1; r += 1
    for i in range(len(s)):
        expand(i, i)
        expand(i, i + 1)
    return s[res_l:res_r + 1]

