var longestPalindrome = function(s) {
    let resL = 0, resR = 0;
    function expand(l, r) {
        while (l >= 0 && r < s.length && s[l] === s[r]) {
            if (r - l > resR - resL) { resL = l; resR = r; }
            l--; r++;
        }
    }
    for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i+1); }
    return s.slice(resL, resR + 1);
};

