        if (w1.length > w2.length && w1.slice(0, minLen) === w2.slice(0, minLen)) return '';
        for (let j = 0; j < minLen; j++) if (w1[j] !== w2[j]) { adj[w1[j]].add(w2[j]); break; }
    }
    const inDeg = Object.fromEntries(Object.keys(adj).map(c => [c, 0]));
    for (const nbs of Object.values(adj)) for (const nb of nbs) inDeg[nb]++;
    const q = Object.keys(inDeg).filter(c => inDeg[c] === 0), res = [];
    while (q.length) {
        const c = q.shift(); res.push(c);
        for (const nb of adj[c]) if (--inDeg[nb] === 0) q.push(nb);
