var pacificAtlantic = function(heights) {
    const [rows, cols] = [heights.length, heights[0].length];
    function bfs(starts) {
        const visited = new Set(starts.map(([r,c]) => r*cols+c));
        const q = [...starts];
        while (q.length) {
            const [r, c] = q.shift();
            for (const [dr, dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
                const [nr, nc] = [r+dr, c+dc];
                const key = nr*cols+nc;
                if (nr>=0&&nr<rows&&nc>=0&&nc<cols&&!visited.has(key)&&heights[nr][nc]>=heights[r][c])
                { visited.add(key); q.push([nr,nc]); }
            }
        }
        return visited;
    }
    const pac = bfs([...Array(rows).keys()].map(r=>[r,0]).concat([...Array(cols).keys()].map(c=>[0,c])));
    const atl = bfs([...Array(rows).keys()].map(r=>[r,cols-1]).concat([...Array(cols).keys()].map(c=>[rows-1,c])));
    return [...pac].filter(k => atl.has(k)).map(k => [Math.floor(k/cols), k%cols]);
};

